int rust_anything_OrdinalDay(int Month, int Day, int LeapYearValue);
bool rust_anything_BetweenDateHoursLeftInclusive(int TestDate, int TestHour, int StartDate, int StartHour, int EndDate, int EndHour);
bool rust_anything_BetweenDates(int TestDate, int StartDate, int EndDate);
double rust_anything_SafeDivide(double a, double b);
double rust_anything_rotAzmDiffDeg(double AzmA, double AzmB);
double rust_anything_epexp(double numerator, double denominator);
double rust_anything_Interp(double Lower, double Upper, double InterpFac);

#endif /* GENERAL_RS_H */
